import { test, expect } from '@playwright/test';

test.describe('Password Requirements Tooltip', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('about:blank');
    await page.setContent(`
      <form>
        <div>
          <label for="password">Password</label>
          <input 
            id="password" 
            type="password" 
            aria-describedby="password-requirements"
            data-testid="password-input"
          />
          <button 
            type="button" 
            id="password-help-btn"
            aria-label="Password requirements"
            title="Password must be at least 8 characters, contain uppercase, lowercase, number, and special character"
          >
            ?
          </button>
          <div 
            id="password-requirements" 
            role="tooltip"
            style="display: none; position: absolute; background: #f0f0f0; padding: 10px; border: 1px solid #ccc; border-radius: 4px;"
          >
            <h4>Password Requirements:</h4>
            <ul>
              <li>At least 8 characters long</li>
              <li>Contains uppercase letter (A-Z)</li>
              <li>Contains lowercase letter (a-z)</li>
              <li>Contains number (0-9)</li>
              <li>Contains special character (!@#$%^&*)</li>
            </ul>
          </div>
        </div>
      </form>
      <script>
        const helpBtn = document.getElementById('password-help-btn');
        const tooltip = document.getElementById('password-requirements');

        helpBtn.addEventListener('click', () => {
          tooltip.style.display = tooltip.style.display === 'none' ? 'block' : 'none';
        });

        helpBtn.addEventListener('mouseenter', () => {
          tooltip.style.display = 'block';
        });

        helpBtn.addEventListener('mouseleave', () => {
          tooltip.style.display = 'none';
        });
      </script>
    `);
  });

  test('should display tooltip when help button is clicked', async ({ page }) => {
    const helpButton = page.getByRole('button', { name: /password requirements/i });
    const tooltip = page.getByRole('tooltip');

    // Initially tooltip should not be visible
    await expect(tooltip).toHaveCSS('display', 'none');

    // Click help button to show tooltip
    await helpButton.click();

    // Tooltip should now be visible
    await expect(tooltip).toHaveCSS('display', 'block');
  });

  test('should display tooltip on hover over help button', async ({ page }) => {
    const helpButton = page.getByRole('button', { name: /password requirements/i });
    const tooltip = page.getByRole('tooltip');

    // Initially tooltip should not be visible
    await expect(tooltip).toHaveCSS('display', 'none');

    // Hover over help button
    await helpButton.hover();

    // Tooltip should now be visible
    await expect(tooltip).toHaveCSS('display', 'block');
  });

  test('should hide tooltip when mouse leaves help button', async ({ page }) => {
    const helpButton = page.getByRole('button', { name: /password requirements/i });
    const tooltip = page.getByRole('tooltip');

    // Hover over help button to show tooltip
    await helpButton.hover();
    await expect(tooltip).toHaveCSS('display', 'block');

    // Move mouse away from button
    await page.mouse.move(0, 0);

    // Tooltip should be hidden
    await expect(tooltip).toHaveCSS('display', 'none');
  });

  test('should contain all password requirement items in tooltip', async ({ page }) => {
    const helpButton = page.getByRole('button', { name: /password requirements/i });
    const tooltip = page.getByRole('tooltip');

    // Show tooltip
    await helpButton.click();

    // Verify tooltip contains all requirements
    await expect(tooltip).toContainText('At least 8 characters long');
    await expect(tooltip).toContainText('Contains uppercase letter (A-Z)');
    await expect(tooltip).toContainText('Contains lowercase letter (a-z)');
    await expect(tooltip).toContainText('Contains number (0-9)');
    await expect(tooltip).toContainText('Contains special character (!@#$%^&*)');
  });

  test('should have proper accessibility attributes on password input', async ({ page }) => {
    const passwordInput = page.getByLabel('Password');

    // Verify input has aria-describedby pointing to tooltip
    await expect(passwordInput).toHaveAttribute('aria-describedby', 'password-requirements');

    // Verify input type is password
    await expect(passwordInput).toHaveAttribute('type', 'password');
  });

  test('should toggle tooltip visibility on multiple clicks', async ({ page }) => {
    const helpButton = page.getByRole('button', { name: /password requirements/i });
    const tooltip = page.getByRole('tooltip');

    // First click - show
    await helpButton.click();
    await expect(tooltip).toHaveCSS('display', 'block');

    // Second click - hide
    await helpButton.click();
    await expect(tooltip).toHaveCSS('display', 'none');

    // Third click - show again
    await helpButton.click();
    await expect(tooltip).toHaveCSS('display', 'block');
  });
});
